/* =====================================================================
   Energy Juice — fictional demo shop logic
   - Works in the browser (auto-wires the DOM UI on load)
   - Exports createCart() for CommonJS / Node usage
   - All amounts are handled internally in cents.
   ===================================================================== */
(function (global) {
  'use strict';

  // ---------------------------------------------------------------------
  // Core cart factory (the part that is exported and unit-testable)
  // ---------------------------------------------------------------------
  function createCart() {
    var FLAVORS = {
      citrus: 299,
      berry: 349,
      tropical: 399
    };

    // id -> integer quantity (only valid flavor ids are ever stored)
    var quantities = {};

    function add(id) {
      if (!FLAVORS.hasOwnProperty(id)) {
        throw new Error('Unknown flavor id: ' + id);
      }
      quantities[id] = (quantities[id] || 0) + 1;
    }

    function setQuantity(id, n) {
      if (!FLAVORS.hasOwnProperty(id)) {
        throw new Error('Unknown flavor id: ' + id);
      }
      if (!Number.isInteger(n) || n < 0) {
        throw new Error('Invalid quantity: ' + n);
      }
      quantities[id] = n;
    }

    function getCount() {
      var count = 0;
      for (var id in quantities) {
        if (Object.prototype.hasOwnProperty.call(quantities, id)) {
          count += quantities[id];
        }
      }
      return count;
    }

    function getTotalCents() {
      var total = 0;
      for (var id in quantities) {
        if (Object.prototype.hasOwnProperty.call(quantities, id)) {
          total += quantities[id] * FLAVORS[id];
        }
      }
      return total;
    }

    function clear() {
      for (var id in quantities) {
        if (Object.prototype.hasOwnProperty.call(quantities, id)) {
          delete quantities[id];
        }
      }
    }

    return {
      add: add,
      setQuantity: setQuantity,
      getCount: getCount,
      getTotalCents: getTotalCents,
      clear: clear
    };
  }

  // ---------------------------------------------------------------------
  // Browser UI wiring (only runs when a DOM is available)
  // ---------------------------------------------------------------------
  function initUI() {
    if (typeof document === 'undefined') return;

    var cart = createCart();
    var FLAVOR_LABELS = {
      citrus: 'Citrus Surge',
      berry: 'Berry Burst',
      tropical: 'Tropical Wave'
    };

    // Bind every "add" button (each click adds exactly one item).
    var addButtons = document.querySelectorAll('[data-flavor]');
    addButtons.forEach(function (btn) {
      btn.addEventListener('click', function () {
        var id = btn.getAttribute('data-flavor');
        cart.add(id);
        renderCart();
      });
    });

    // Clear button.
    var clearBtn = document.getElementById('cart-clear');
    if (clearBtn) {
      clearBtn.addEventListener('click', function () {
        cart.clear();
        renderCart();
      });
    }

    // Render the cart DOM from the cart state.
    function renderCart() {
      var countEl = document.getElementById('cart-count');
      var totalEl = document.getElementById('cart-total');
      var lineItemsEl = document.getElementById('cart-line-items');

      if (countEl) countEl.textContent = String(cart.getCount());
      if (totalEl) totalEl.textContent = cart.getTotalCents() + ' cents';

      var ids = [];
      for (var id in quantities) {
        if (Object.prototype.hasOwnProperty.call(quantities, id)) ids.push(id);
      }
      ids.sort();

      lineItemsEl.innerHTML = '';
      if (ids.length === 0) {
        var empty = document.createElement('li');
        empty.className = 'cart-line cart-line--empty';
        empty.textContent = 'Your demo cart is empty.';
        lineItemsEl.appendChild(empty);
      } else {
        ids.forEach(function (id) {
          var li = document.createElement('li');
          li.className = 'cart-line';
          li.innerHTML =
            '<span class="cart-line__name">' + FLAVOR_LABELS[id] + '</span>' +
            '<span class="cart-line__qty">x' + quantities[id] + '</span>';
          lineItemsEl.appendChild(li);
        });
      }
    }

    renderCart();
  }

  // ---------------------------------------------------------------------
  // Exports: CommonJS, AMD, and browser global.
  // ---------------------------------------------------------------------
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { createCart: createCart };
  } else if (typeof window !== 'undefined') {
    window.createCart = createCart;
    window.initUI = initUI;
    window.__cart = createCart();
    initUI();
  }
})(typeof globalThis !== 'undefined' ? globalThis : this);

