/* =====================================================================
   Energy Juice — fictional demo shop styles
   No external dependencies. Responsive: mobile ~390px, desktop ~1440px.
   ===================================================================== */

:root {
  --bg: #0f1226;
  --bg-soft: #191d3a;
  --surface: #ffffff;
  --surface-2: #f4f6ff;
  --text: #1a1d2e;
  --text-muted: #5b6078;
  --accent: #ff5a3c;
  --accent-2: #ffb020;
  --berry: #7b3ff2;
  --tropical: #00c2a8;
  --citrus: #ff9f1c;
  --border: #e4e8f5;
  --shadow: 0 10px 30px rgba(20, 24, 60, 0.12);
  --radius: 16px;
  --radius-sm: 10px;
  --font: "Segoe UI", system-ui, -apple-system, Roboto, Helvetica, Arial, sans-serif;
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  font-family: var(--font);
  color: var(--text);
  background: linear-gradient(180deg, #eef1ff 0%, #f7f8ff 100%);
  line-height: 1.5;
  min-height: 100vh;
}

/* ---- Accessibility helpers ---- */
.skip-link {
  position: absolute;
  left: 8px;
  top: 8px;
  background: var(--accent);
  color: #fff;
  padding: 8px 14px;
  border-radius: var(--radius-sm);
  z-index: 100;
  text-decoration: none;
}
.skip-link[hidden] {
  display: none;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ---- Header ---- */
.site-header {
  background: linear-gradient(135deg, var(--accent) 0%, var(--accent-2) 100%);
  color: #fff;
  box-shadow: var(--shadow);
}
.site-header__inner {
  max-width: 1440px;
  margin: 0 auto;
  padding: 22px 28px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
}
.brand {
  display: flex;
  align-items: center;
  gap: 12px;
}
.brand__mark {
  font-size: 2rem;
  line-height: 1;
}
.brand__name {
  font-size: 1.6rem;
  font-weight: 800;
  letter-spacing: 0.3px;
}
.brand__tagline {
  margin: 0;
  font-size: 0.95rem;
  opacity: 0.95;
  font-weight: 500;
}

/* ---- Demo banner ---- */
.demo-banner {
  max-width: 1440px;
  margin: 22px auto 4px;
  padding: 12px 20px;
  background: #fff6e6;
  border: 1px solid #ffd88a;
  border-left-width: 6px;
  border-left-color: var(--accent);
  border-radius: var(--radius-sm);
  color: #5a4300;
  font-size: 0.95rem;
  box-shadow: var(--shadow);
}
.demo-banner strong {
  color: #7a5600;
}

/* ---- Shop layout ---- */
.shop-layout {
  max-width: 1440px;
  margin: 16px auto 32px;
  padding: 0 24px;
  display: grid;
  gap: 28px;
  align-items: start;
}

/* ---- Products ---- */
.products__heading {
  font-size: 1.4rem;
  margin: 0 0 16px;
}
.products__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 22px;
  grid-template-columns: repeat(3, 1fr);
}
.product {
  position: relative;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px;
  box-shadow: var(--shadow);
  transition: transform 0.18s ease, box-shadow 0.18s ease;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.product:hover {
  transform: translateY(-4px);
  box-shadow: 0 18px 40px rgba(20, 24, 60, 0.18);
}
.product__badge {
  position: absolute;
  top: 14px;
  right: 14px;
  background: var(--accent);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.6px;
  padding: 4px 8px;
  border-radius: 999px;
  text-transform: uppercase;
}
.product__swatch {
  width: 100%;
  height: 120px;
  border-radius: var(--radius-sm);
  box-shadow: inset 0 0 0 1px rgba(0, 0, 0, 0.06);
}
.product--citrus .product__swatch {
  background: linear-gradient(135deg, var(--citrus), #ffd24a);
}
.product--berry .product__swatch {
  background: linear-gradient(135deg, var(--berry), #b06bff);
}
.product--tropical .product__swatch {
  background: linear-gradient(135deg, var(--tropical), #4be3c9);
}
.product__name {
  margin: 0;
  font-size: 1.25rem;
}
.product__tagline {
  margin: 0;
  color: var(--text-muted);
  font-size: 0.92rem;
  min-height: 2.6em;
}
.product__price {
  margin: 4px 0 8px;
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--accent);
}

/* ---- Buttons ---- */
.btn {
  font-family: var(--font);
  font-size: 0.98rem;
  font-weight: 700;
  cursor: pointer;
  border: 0;
  border-radius: var(--radius-sm);
  padding: 12px 18px;
  transition: filter 0.15s ease, transform 0.1s ease, box-shadow 0.15s ease;
}
.btn:active {
  transform: translateY(1px);
}
.btn--add {
  margin-top: auto;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  color: #fff;
  box-shadow: 0 8px 18px rgba(255, 90, 60, 0.35);
}
.btn--add:hover {
  filter: brightness(1.06);
}
.btn--add:focus-visible,
.btn--clear:focus-visible {
  outline: 3px solid #ffb020;
  outline-offset: 2px;
}
.btn--clear {
  width: 100%;
  background: #e9ecf7;
  color: var(--text);
  border: 1px solid var(--border);
}
.btn--clear:hover {
  background: #dde1f2;
}

/* ---- Cart ---- */
.cart {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px;
  box-shadow: var(--shadow);
  position: sticky;
  top: 20px;
}
.cart__heading {
  margin: 0 0 4px;
  font-size: 1.35rem;
}
.cart-note {
  margin: 0 0 14px;
  color: var(--text-muted);
  font-size: 0.88rem;
}
.cart-line-items {
  list-style: none;
  margin: 0 0 14px;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 20px;
}
.cart-line {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
}
.cart-line--empty {
  color: var(--text-muted);
  font-size: 0.92rem;
  background: transparent;
  border: 0;
  padding: 4px 0;
}
.cart-line__name {
  font-weight: 600;
}
.cart-line__qty {
  color: var(--text-muted);
  font-size: 0.9rem;
}

.cart-summary {
  border-top: 1px solid var(--border);
  padding-top: 12px;
  margin: 4px 0 16px;
}
.cart-summary__row {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 8px;
}
.cart-summary__row--total {
  margin-bottom: 0;
  padding-top: 10px;
  border-top: 1px dashed var(--border);
  font-size: 1.1rem;
}
.cart-summary__label {
  color: var(--text-muted);
  font-size: 0.95rem;
}
.cart-summary__value {
  font-variant-numeric: tabular-nums;
}
.cart-summary__value[data-testid="cart-total"] {
  color: var(--accent);
  font-weight: 800;
}

/* ---- How it works ---- */
.how-it-works {
  max-width: 1440px;
  margin: 8px auto 40px;
  padding: 0 24px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 24px 26px;
  box-shadow: var(--shadow);
}
.how-it-works h2 {
  margin: 0 0 12px;
  font-size: 1.25rem;
}
.how-it-works ul {
  margin: 0;
  padding-left: 20px;
  color: var(--text-muted);
}
.how-it-works li {
  margin-bottom: 8px;
}
.how-it-works em {
  font-style: normal;
  font-weight: 600;
  color: var(--text);
}

/* ---- Footer ---- */
.site-footer {
  background: var(--bg);
  color: #c7ccd9;
  text-align: center;
  padding: 24px 20px;
  font-size: 0.88rem;
}
.site-footer p {
  margin: 0;
}

/* =====================================================================
   Responsive — mobile (~390px)
   ===================================================================== */
@media (max-width: 860px) {
  .shop-layout {
    grid-template-columns: 1fr;
    gap: 22px;
  }
  .cart {
    position: static;
    order: -1;
  }
  .products__list {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .site-header__inner {
    padding: 18px 18px;
  }
  .brand__name {
    font-size: 1.35rem;
  }
  .shop-layout {
    padding: 0 16px;
  }
  .how-it-works {
    padding: 18px;
  }
  .product__swatch {
    height: 100px;
  }
  .btn--add {
    padding: 12px 14px;
  }
}

/* ---- Large desktop (~1440px) ---- */
@media (min-width: 1441px) {
  .shop-layout {
    gap: 40px;
  }
  .products__list {
    gap: 26px;
  }
  .product {
    padding: 26px;
  }
  .product__swatch {
    height: 150px;
  }
}

