  if (sel.includes('cart-clear')) return clearEl;
  if (sel.includes('main')) return mainEl;
  return null;
}
function getAll(sel) {
  if (sel.includes('data-flavor')) return flavorButtons;
  return [];
}

const document = {
  querySelector: getEl,
  querySelectorAll: getAll,
};

const sandbox = { module: { exports: {} }, document, console, Object, Number };
sandbox.globalThis = sandbox;
vm.createContext(sandbox);

const code = fs.readFileSync('/workspace/shop.js', 'utf8');
vm.runInContext(code, sandbox, { filename: 'shop.js' });

const { createCart } = sandbox.module.exports;

let failures = 0;
function assert(cond, msg) {
  if (cond) console.log('  PASS:', msg);
  else { console.log('  FAIL:', msg); failures++; }
}

console.log('\n== CommonJS API ==');
const cart = createCart();
assert(cart.getTotalCents() === 0, 'empty total is 0 cents');
assert(cart.getCount() === 0, 'empty count is 0');

cart.add('citrus');
assert(cart.getCount() === 1, 'add citrus -> count 1');
assert(cart.getTotalCents() === 299, 'add citrus -> 299 cents');

cart.add('citrus');
assert(cart.getCount() === 2, 'add citrus again -> count 2');
assert(cart.getTotalCents() === 598, 'two citrus -> 598 cents');

cart.add('berry');
assert(cart.getCount() === 3, 'add berry -> count 3');
assert(cart.getTotalCents() === 947, 'citrus x2 + berry -> 947 cents');

cart.add('tropical');
assert(cart.getTotalCents() === 1346, 'add tropical -> 1346 cents');

// unknown id rejected without mutation
const beforeCount = cart.getCount();
const beforeTotal = cart.getTotalCents();
cart.add('unknown');
assert(cart.getCount() === beforeCount, 'add unknown id does not change count');
assert(cart.getTotalCents() === beforeTotal, 'add unknown id does not change total');
assert(!('unknown' in cart), 'unknown id not stored');

// setQuantity valid
cart.setQuantity('citrus', 4);
assert(cart.getCount() === 6, 'setQuantity citrus=4 -> count 6');
assert(cart.getTotalCents() === 1785, 'setQuantity citrus=4 -> total 1785 cents');

// setQuantity negative rejected
cart.setQuantity('citrus', -1);
assert(cart.getCount() === 6, 'setQuantity negative rejected -> count unchanged');
assert(cart.getTotalCents() === 1785, 'setQuantity negative rejected -> total unchanged');

// setQuantity non-integer rejected
cart.setQuantity('citrus', 2.5);
assert(cart.getCount() === 6, 'setQuantity non-integer rejected -> count unchanged');

// setQuantity NaN rejected
cart.setQuantity('citrus', NaN);
assert(cart.getCount() === 6, 'setQuantity NaN rejected -> count unchanged');

// setQuantity unknown rejected
cart.setQuantity('nope', 3);
assert(cart.getTotalCents() === 1785, 'setQuantity unknown rejected -> total unchanged');

// setQuantity 0 allowed (integer, not negative)
cart.setQuantity('tropical', 0);
assert(cart.getCount() === 5, 'setQuantity 0 allowed -> count 5');
assert(cart.getTotalCents() === 1176, 'setQuantity 0 -> total 1176 cents');

// clear
cart.clear();
assert(cart.getCount() === 0, 'clear -> count 0');
assert(cart.getTotalCents() === 0, 'clear -> total 0');

console.log('\n== DOM wiring ==');
assert(countEl.textContent === '0', 'DOM count starts at 0');
assert(totalEl.textContent === '$0.00', 'DOM total starts at $0.00');

// click each flavor button exactly once
flavorButtons.forEach(b => b.onclick({ target: b }));
assert(countEl.textContent === '3', 'one click of each flavor -> count 3 (adds exactly one)');
assert(totalEl.textContent === '$10.47', 'one click of each -> $10.47 (299+349+399)');

// click citrus again -> still +1 (no double-add)
flavorButtons[0].onclick({ target: flavorButtons[0] });
assert(countEl.textContent === '4', 'second citrus click -> count 4 (still exactly one)');

// clear updates DOM
clearEl.onclick({ target: clearEl });
assert(countEl.textContent === '0', 'clear updates DOM count to 0');
assert(totalEl.textContent === '$0.00', 'clear updates DOM total to $0.00');

console.log('\n' + (failures === 0 ? 'ALL TESTS PASSED' : failures + ' TEST(S) FAILED'));
process.exit(failures === 0 ? 0 : 1);
