import csv
import io
from decimal import Decimal, InvalidOperation

_REQUIRED_COLUMNS = {"customer", "amount", "status"}


def totals(csv_text):
    """Return a dict mapping each customer to their total balance in integer cents.

    Only rows with ``status == "posted"`` are summed; ``pending`` rows are ignored.
    Amounts are parsed with :class:`decimal.Decimal` so cents stay exact.
    Malformed amounts or missing required columns raise :class:`ValueError`.
    """
    reader = csv.DictReader(io.StringIO(csv_text))

    if reader.fieldnames is None:
        raise ValueError("empty CSV input")

    header = set(reader.fieldnames)
    missing = _REQUIRED_COLUMNS - header
    if missing:
        raise ValueError("missing required columns: " + ", ".join(sorted(missing)))

    totals = {}
    for row in reader:
        if row.get("status") != "posted":
            continue

        customer = row.get("customer")
        amount_str = row.get("amount")
        if customer is None or amount_str is None:
            raise ValueError("row missing customer or amount")

        try:
            amount = Decimal(amount_str)
        except InvalidOperation:
            raise ValueError("malformed amount: %r" % (amount_str,))
        if not amount.is_finite():
            raise ValueError("malformed amount: %r" % (amount_str,))

        cents = int((amount * 100).to_integral_value())
        totals[customer] = totals.get(customer, 0) + cents

    return totals

