/**
 * Energy Juice Demo Shop - Cart Management
 * 
 * This module provides cart functionality for the demo shop.
 * Uses cents internally to avoid floating-point precision issues.
 */

// Cart state (browser-compatible)
let cart = {};

/**
 * Cart Manager - Create a new cart instance
 * @returns {CartManager} Cart manager instance
 */
function createCart() {
  const self = {
    _cart: {},

    /**
     * Add an item to the cart
     * @param {string} id - The product ID (citrus, berry, tropical)
     * @returns {boolean} true if added, false if rejected
     */
    add(id) {
      // Validate ID exists
      const validIds = ['citrus', 'berry', 'tropical'];
      if (!validIds.includes(id)) {
        console.warn(`Unknown product ID: ${id}`);
        return false;
      }

      // Initialize cart entry if not exists
      if (!this._cart[id]) {
        this._cart[id] = {
          id: id,
          quantity: 1,
          price: this._getPrice(id)
        };
      } else {
        this._cart[id].quantity += 1;
      }
      return true;
    },

    /**
     * Set quantity for an item in the cart
     * @param {string} id - The product ID
     * @param {number} n - The new quantity
     * @returns {boolean} true if updated, false if rejected
     */
    setQuantity(id, n) {
      // Validate ID exists
      const validIds = ['citrus', 'berry', 'tropical'];
      if (!validIds.includes(id)) {
        console.warn(`Unknown product ID: ${id}`);
        return false;
      }

      // Validate quantity is a non-negative integer
      if (!Number.isInteger(n) || n < 0) {
        console.warn(`Invalid quantity for ${id}: ${n} (must be non-negative integer)`);
        return false;
      }

      // Update quantity
      this._cart[id].quantity = n;
      return true;
    },

    /**
     * Get the total count of items in cart
     * @returns {number} Total item count
     */
    getCount() {
      let count = 0;
      for (const item of Object.values(this._cart)) {
        count += item.quantity;
      }
      return count;
    },

    /**
     * Get the total price in cents
     * @returns {number} Total price in cents
     */
    getTotalCents() {
      let total = 0;
      for (const item of Object.values(this._cart)) {
        total += item.quantity * item.price;
      }
      return total;
    },

    /**
     * Clear all items from the cart
     */
    clear() {
      this._cart = {};
    },

    /**
     * Get cart item by ID
     * @param {string} id - The product ID
     * @returns {object|null} Cart item or null if not found
     */
    getItem(id) {
      return this._cart[id] || null;
    },

    /**
     * Get cart items list
     * @returns {Array} Array of cart items
     */
    getItems() {
      return Object.values(this._cart);
    },

    /**
     * Get price for a flavor (internal helper)
     * @param {string} id - The product ID
     * @returns {number} Price in cents
     */
    _getPrice(id) {
      const prices = {
        citrus: 299,
        berry: 349,
        tropical: 399
      };
      return prices[id] || 0;
    }
  };

  return self;
}

// Export for browser and CommonJS
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { createCart };
}

// Browser global
if (typeof window !== 'undefined') {
  window.createCart = createCart;
}

styles.css.text:
/* Energy Juice Demo Shop Styles */
:root {
  --primary-color: #ff6b35;
  --secondary-color: #f7c59f;
  --accent-color: #004e89;
  --bg-color: #f8f9fa;
  --card-bg: #ffffff;
  --text-color: #333333;
  --border-color: #e9ecef;
  --success-color: #28a745;
  --error-color: #dc3545;
  --shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 4px 16px rgba(0, 0, 0, 0.15);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, sans-serif;
  background-color: var(--bg-color);
  color: var(--text-color);
  line-height: 1.6;
  min-height: 100vh;
}

/* Header */
.header {
  background: linear-gradient(135deg, var(--primary-color), var(--accent-color));
  color: white;
  padding: 2rem 1rem;
  text-align: center;
}

.logo {
  font-size: 2rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
}

.subtitle {
  font-size: 0.95rem;
  opacity: 0.9;
}

/* Container */
.container {
  max-width: 1440px;
  margin: 0 auto;
  padding: 2rem 1rem;
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
}

/* Products Section */
.products {
  flex: 1 1 600px;
  min-width: 300px;
}

.products h2 {
  font-size: 1.5rem;
  margin-bottom: 1.5rem;
  color: var(--accent-color);
  text-align: center;
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
}

.product {
  background: var(--card-bg);
  border-radius: 12px;
  padding: 1.5rem;
  box-shadow: var(--shadow);
  transition: transform 0.2s, box-shadow 0.2s;
  text-align: center;
}

.product:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.product-image {
  font-size: 4rem;
  margin-bottom: 1rem;
}

.product-name {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 0.5rem;
  color: var(--accent-color);
}

.product-desc {
  font-size: 0.9rem;
  color: #666;
  margin-bottom: 0.5rem;
}

.product-price {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--primary-color);
  margin-bottom: 1rem;
}

.add-btn {
  background: var(--primary-color);
  color: white;
  border: none;
  padding: 0.75rem 1.5rem;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  width: 100%;
}

.add-btn:hover {
  background: #e55a2b;
}

.add-btn:active {
  transform: scale(0.98);
}

.add-btn:focus {
  outline: 2px solid var(--accent-color);
  outline-offset: 2px;
}

/* Cart Section */
.cart-section {
  flex: 1 1 350px;
  min-width: 280px;
  background: var(--card-bg);
  border-radius: 12px;
  padding: 1.5rem;
  box-shadow: var(--shadow);
  height: fit-content;
}

.cart-section h2 {
  font-size: 1.25rem;
  margin-bottom: 1rem;
  color: var(--accent-color);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.cart-items {
  min-height: 100px;
  max-height: 300px;
  overflow-y: auto;
  margin-bottom: 1rem;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  padding: 0.5rem;
}

.empty-cart {
  color: #999;
  text-align: center;
  padding: 1rem;
  font-style: italic;
}

.cart-item {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.75rem;
  border-bottom: 1px solid var(--border-color);
}

.cart-item:last-child {
  border-bottom: none;
}

.cart-item-info {
  flex: 1;
}

.cart-item-name {
  font-weight: 600;
  font-size: 0.95rem;
}

.cart-item-price {
  font-size: 0.85rem;
  color: #666;
}

.cart-item-quantity {
  font-weight: 700;
  color: var(--primary-color);
  margin-right: 0.5rem;
}

.cart-item-total {
  font-weight: 600;
}

/* Cart Summary */
.cart-summary {
  border-top: 2px solid var(--border-color);
  padding-top: 1rem;
}

.cart-count,
.cart-total {
  display: flex;
  justify-content: space-between;
  margin-bottom: 0.5rem;
  font-size: 0.95rem;
}

.cart-total {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--accent-color);
}

.clear-btn {
  width: 100%;
  background: var(--error-color);
  color: white;
  border: none;
  padding: 0.75rem;
  border-radius: 8px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s;
  margin-top: 0.5rem;
}

.clear-btn:hover {
  background: #c82333;
}

.clear-btn:focus {
  outline: 2px solid var(--accent-color);
  outline-offset: 2px;
}

/* Footer */
.footer {
  text-align: center;
  padding: 1.5rem;
  color: #666;
  font-size: 0.85rem;
  margin-top: auto;
}

/* Responsive Design */
@media (max-width: 768px) {
  .container {
    padding: 1rem 0.75rem;
    flex-direction: column;
  }

  .products {
    min-width: 100%;
  }

  .cart-section {
    min-width: 100%;
  }

  .product-grid {
    grid-template-columns: 1fr;
  }

  .logo {
    font-size: 1.5rem;
  }

  .product-image {
    font-size: 3rem;
  }
}

@media (max-width: 480px) {
  .container {
    padding: 0.75rem 0.5rem;
  }

  .header {
    padding: 1.5rem 0.75rem;
