/**
 * Energy Juice Demo Shop - Cart Management
 * 
 * This module provides cart functionality for the demo shop.
 * Uses cents internally to avoid floating-point precision issues.
 */

// Cart state (browser-compatible)
let cart = {};

/**
 * Cart Manager - Create a new cart instance
 * @returns {CartManager} Cart manager instance
 */
function createCart() {
  const self = {
    _cart: {},

    /**
     * Add an item to the cart
     * @param {string} id - The product ID (citrus, berry, tropical)
     * @returns {boolean} true if added, false if rejected
     */
    add(id) {
      // Validate ID exists
      const validIds = ['citrus', 'berry', 'tropical'];
      if (!validIds.includes(id)) {
        console.warn(`Unknown product ID: ${id}`);
        return false;
      }

      // Initialize cart entry if not exists
      if (!this._cart[id]) {
        this._cart[id] = {
          id: id,
          quantity: 1,
          price: this._getPrice(id)
        };
      } else {
        this._cart[id].quantity += 1;
      }
      return true;
    },

    /**
     * Set quantity for an item in the cart
     * @param {string} id - The product ID
     * @param {number} n - The new quantity
     * @returns {boolean} true if updated, false if rejected
     */
    setQuantity(id, n) {
      // Validate ID exists
      const validIds = ['citrus', 'berry', 'tropical'];
      if (!validIds.includes(id)) {
        console.warn(`Unknown product ID: ${id}`);
        return false;
      }

      // Validate quantity is a non-negative integer
      if (!Number.isInteger(n) || n < 0) {
        console.warn(`Invalid quantity for ${id}: ${n} (must be non-negative integer)`);
        return false;
      }

      // Update quantity
      this._cart[id].quantity = n;
      return true;
    },

    /**
     * Get the total count of items in cart
     * @returns {number} Total item count
     */
    getCount() {
      let count = 0;
      for (const item of Object.values(this._cart)) {
        count += item.quantity;
      }
      return count;
    },

    /**
     * Get the total price in cents
     * @returns {number} Total price in cents
     */
    getTotalCents() {
      let total = 0;
      for (const item of Object.values(this._cart)) {
        total += item.quantity * item.price;
      }
      return total;
    },

    /**
     * Clear all items from the cart
     */
    clear() {
      this._cart = {};
    },

    /**
     * Get cart item by ID
     * @param {string} id - The product ID
     * @returns {object|null} Cart item or null if not found
     */
    getItem(id) {
      return this._cart[id] || null;
    },

    /**
     * Get cart items list
     * @returns {Array} Array of cart items
     */
    getItems() {
      return Object.values(this._cart);
    },

    /**
     * Get price for a flavor (internal helper)
     * @param {string} id - The product ID
     * @returns {number} Price in cents
     */
    _getPrice(id) {
      const prices = {
        citrus: 299,
        berry: 349,
        tropical: 399
      };
      return prices[id] || 0;
    }
  };

  return self;
}

// Export for browser and CommonJS
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { createCart };
}

// Browser global
if (typeof window !== 'undefined') {
  window.createCart = createCart;
}
EOF"}

