const prices = { citrus: 299, berry: 349, tropical: 399 };

function createCart() {
  let q = {};
  return {
    add(id) {
      // Reject unknown IDs
      if (typeof prices[id] === 'undefined') {
        return;
      }
      q[id] = (q[id] || 0) + 1;
    },
    setQuantity(id, n) {
      // Reject unknown IDs
      if (typeof prices[id] === 'undefined') {
        return;
      }
      // Reject negative/non-integer quantities
      if (typeof n !== 'number' || n <= 0 || !Number.isInteger(n)) {
        return;
      }
      q[id] = n;
    },
    getCount() {
      return Object.values(q).reduce((a, b) => a + b, 0);
    },
    getTotalCents() {
      return Object.entries(q).reduce((a, [id, n]) => a + prices[id] * n, 0);
    },
    clear() {
      q = {};
    }
  };
}

if (typeof module !== 'undefined') {
  module.exports = { createCart };
}

if (typeof document !== 'undefined') {
  let cart = createCart();
  function update() {
    document.querySelector('[data-testid=cart-count]').textContent = cart.getCount();
    document.querySelector('[data-testid=cart-total]').textContent = '$' + (cart.getTotalCents() / 100).toFixed(2);
  }
  document.querySelectorAll('[data-flavor]').forEach(b => b.onclick = () => {
    cart.add(b.dataset.flavor);
    update();
  });
  document.querySelector('[data-testid=cart-clear]').onclick = () => {
    cart.clear();
    update();
  };
}

