  module.exports = { createCart };
}

if (typeof document !== 'undefined') {
  let cart = createCart();
  function update() {
    document.querySelector('[data-testid=cart-count]').textContent = cart.getCount();
    document.querySelector('[data-testid=cart-total]').textContent = '$' + (cart.getTotalCents() / 100).toFixed(2);
  }
  document.querySelectorAll('[data-flavor]').forEach(b => b.onclick = () => {
    cart.add(b.dataset.flavor);
    update();
  });
  document.querySelector('[data-testid=cart-clear]').onclick = () => {
    cart.clear();
    update();
  };
}
